pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialBalance, uint256 deposit, address user) public {
        vm.assume(user != address(0) && user != address(this));
        // keep initialBalance and deposit within a range where overflow is possible when initialBalance is high
        initialBalance = bound(initialBalance, 0, type(uint256).max - 1);
        deposit = bound(deposit, 0, type(uint256).max);

        // set up the user's initial balance by directly manipulating the storage via a deposit
        // we must use addToBalance to set the balance, but the overflow check in the reference version
        // prevents overflow. So we use the withdrawBalance to reset, but we need a pre-existing balance.
        // We can use vm.deal and prank to first deposit an amount that is guaranteed not to overflow.
        vm.deal(user, initialBalance);
        vm.prank(user);
        c.addToBalance{value: initialBalance}();

        // record balance before the potentially overflowing deposit
        uint256 balanceBefore = c.getBalance(user);

        // perform the deposit that might overflow
        vm.deal(user, deposit);
        vm.prank(user);
        c.addToBalance{value: deposit}();

        uint256 balanceAfter = c.getBalance(user);

        // In the correct contract, balanceAfter should always be >= balanceBefore
        // because either the overflow check prevented the deposit (reverting) or the addition succeeded without overflow.
        // In the buggy contract, balanceAfter can be < balanceBefore if overflow occurs.
        // We use try/catch to detect revert.
        // Actually, we need to capture the revert behavior of the second deposit.
        // Let's redo the test to wrap the second deposit in try/catch.

        // Re-execute the setup
        c = new C();
        vm.deal(user, initialBalance);
        vm.prank(user);
        c.addToBalance{value: initialBalance}();
        balanceBefore = c.getBalance(user);

        vm.deal(user, deposit);
        vm.prank(user);
        bool success;
        try c.addToBalance{value: deposit}() {
            success = true;
            balanceAfter = c.getBalance(user);
        } catch {
            success = false;
            balanceAfter = balanceBefore; // no change
        }

        // Property: if the call succeeded, the balance must not have decreased.
        // In the reference contract, overflow reverts, so success=false and balance unchanged.
        // In the buggy contract, overflow succeeds and balanceAfter < balanceBefore.
        assertTrue(!success || balanceAfter >= balanceBefore);
    }
}

